import os
import subprocess
import shutil
from docx import Document
from pptx import Presentation

# Define keywords for each category
keywords = {
    'LLM': ['language model', 'large language', 'llm', 'transformer', 'gpt', 'bert', 'attention mechanism', 
            'neural network', 'nlp', 'natural language', 'token', 'embedding', 'fine-tuning', 'prompt',
            'chatgpt', 'deep learning', 'machine learning', 'text generation', 'language understanding'],
    'trapped_ion_and_qc': ['trapped ion', 'ion trap', 'quantum computing', 'qubit', 'quantum gate', 
                           'entanglement', 'quantum information', 'quantum processor', 'quantum algorithm',
                           'quantum error', 'quantum memory', 'quantum simulation', 'quantum state',
                           'superposition', 'decoherence', 'quantum control', 'laser cooling', 'paul trap',
                           'quantum logic', 'quantum bit', 'quantum circuit', 'quantum operation'],
    'black_hole': ['black hole', 'event horizon', 'hawking', 'gravitational', 'singularity', 'spacetime',
                   'general relativity', 'schwarzschild', 'kerr', 'accretion', 'gravitational wave',
                   'cosmic', 'astrophysic', 'neutron star', 'pulsar', 'quasar', 'dark matter', 'dark energy',
                   'cosmolog', 'galaxy', 'supermassive', 'stellar', 'gravity'],
    'DNA': ['dna', 'genome', 'nucleotide', 'genetic', 'sequencing', 'crispr', 'gene', 'chromosome',
            'mutation', 'protein', 'rna', 'transcription', 'replication', 'helix', 'base pair',
            'molecular biology', 'cell', 'enzyme', 'amino acid', 'biolog', 'organism', 'evolution'],
    'music_history': ['music', 'composer', 'symphony', 'baroque', 'classical music', 'beethoven', 'mozart',
                      'bach', 'opera', 'orchestra', 'sonata', 'concerto', 'musical', 'instrument',
                      'melody', 'harmony', 'rhythm', 'romantic period', 'renaissance music', 'choir',
                      'piano', 'violin', 'conductor']
}

def extract_pdf_text(filepath):
    try:
        result = subprocess.run(['pdftotext', filepath, '-'], capture_output=True, text=True, timeout=30)
        return result.stdout.lower()
    except:
        return ''

def extract_docx_text(filepath):
    try:
        doc = Document(filepath)
        text = ' '.join([para.text for para in doc.paragraphs])
        return text.lower()
    except:
        return ''

def extract_pptx_text(filepath):
    try:
        prs = Presentation(filepath)
        text = []
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, 'text'):
                    text.append(shape.text)
        return ' '.join(text).lower()
    except:
        return ''

def classify_file(text):
    scores = {}
    for category, kws in keywords.items():
        score = 0
        for kw in kws:
            score += text.count(kw.lower())
        scores[category] = score

    # Find the category with highest score
    max_score = max(scores.values())
    if max_score == 0:
        return 'music_history'  # Default category if no keywords found

    for cat, score in scores.items():
        if score == max_score:
            return cat
    return 'music_history'

def main():
    source_dir = 'papers/all'
    dest_dirs = {
        'LLM': 'papers/LLM',
        'trapped_ion_and_qc': 'papers/trapped_ion_and_qc',
        'black_hole': 'papers/black_hole',
        'DNA': 'papers/DNA',
        'music_history': 'papers/music_history'
    }

    files = os.listdir(source_dir)

    for filename in files:
        filepath = os.path.join(source_dir, filename)
        if not os.path.isfile(filepath):
            continue

        # Extract text based on file type
        if filename.lower().endswith('.pdf'):
            text = extract_pdf_text(filepath)
        elif filename.lower().endswith('.docx'):
            text = extract_docx_text(filepath)
        elif filename.lower().endswith('.pptx'):
            text = extract_pptx_text(filepath)
        else:
            text = ''

        # Classify
        category = classify_file(text)

        # Move file
        dest_path = os.path.join(dest_dirs[category], filename)
        shutil.move(filepath, dest_path)
        print(f'{filename} -> {category}')

if __name__ == '__main__':
    main()
